import React, { useState } from 'react';
import { useMutation, gql } from '@apollo/client';
import './AddShipmentModal.css';

const ADD_SHIPMENT_MUTATION = gql`
  mutation AddShipment($input: ShipmentInput!) {
    addShipment(input: $input) {
      id
      trackingNumber
      origin
      destination
      status
      carrier
      weight
      dimensions
      estimatedDelivery
      customerName
      customerEmail
    }
  }
`;

const AddShipmentModal = ({ onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    trackingNumber: '',
    origin: '',
    destination: '',
    status: 'PENDING',
    carrier: '',
    weight: '',
    dimensions: '',
    estimatedDelivery: '',
    customerName: '',
    customerEmail: '',
  });

  const [addShipment, { loading }] = useMutation(ADD_SHIPMENT_MUTATION, {
    onCompleted: () => {
      onSuccess();
    },
    onError: (error) => {
      const errorMessage = error.networkError 
        ? 'Network error. Please check backend connection.'
        : error.message || 'Error adding shipment';
      alert('Error: ' + errorMessage);
    },
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Validate required fields
    if (!formData.trackingNumber || !formData.origin || !formData.destination || 
        !formData.carrier || !formData.customerName || !formData.customerEmail) {
      alert('Please fill in all required fields');
      return;
    }

    addShipment({
      variables: {
        input: {
          ...formData,
          weight: parseFloat(formData.weight) || 0,
          estimatedDelivery: formData.estimatedDelivery
            ? `${formData.estimatedDelivery}T00:00:00.000Z`
            : new Date().toISOString(), // Default to today if not provided
        },
      },
    });
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Add New Shipment</h2>
          <button className="close-button" onClick={onClose}>×</button>
        </div>

        <form onSubmit={handleSubmit} className="add-shipment-form">
          <div className="form-section">
            <h3>Tracking Information</h3>
            <div className="form-row">
              <div className="form-group">
                <label>Tracking Number *</label>
                <input
                  type="text"
                  name="trackingNumber"
                  value={formData.trackingNumber}
                  onChange={handleInputChange}
                  required
                  placeholder="TRK000001"
                />
              </div>
              <div className="form-group">
                <label>Status *</label>
                <select
                  name="status"
                  value={formData.status}
                  onChange={handleInputChange}
                  required
                >
                  <option value="PENDING">Pending</option>
                  <option value="IN_TRANSIT">In Transit</option>
                  <option value="DELIVERED">Delivered</option>
                  <option value="CANCELLED">Cancelled</option>
                </select>
              </div>
            </div>
          </div>

          <div className="form-section">
            <h3>Route Information</h3>
            <div className="form-row">
              <div className="form-group">
                <label>Origin *</label>
                <input
                  type="text"
                  name="origin"
                  value={formData.origin}
                  onChange={handleInputChange}
                  required
                  placeholder="New York"
                />
              </div>
              <div className="form-group">
                <label>Destination *</label>
                <input
                  type="text"
                  name="destination"
                  value={formData.destination}
                  onChange={handleInputChange}
                  required
                  placeholder="Los Angeles"
                />
              </div>
            </div>
          </div>

          <div className="form-section">
            <h3>Shipping Details</h3>
            <div className="form-row">
              <div className="form-group">
                <label>Carrier *</label>
                <input
                  type="text"
                  name="carrier"
                  value={formData.carrier}
                  onChange={handleInputChange}
                  required
                  placeholder="FedEx, UPS, DHL..."
                />
              </div>
              <div className="form-group">
                <label>Weight (lbs) *</label>
                <input
                  type="number"
                  name="weight"
                  value={formData.weight}
                  onChange={handleInputChange}
                  required
                  step="0.01"
                  min="0"
                  placeholder="10.5"
                />
              </div>
            </div>
            <div className="form-row">
              <div className="form-group">
                <label>Dimensions *</label>
                <input
                  type="text"
                  name="dimensions"
                  value={formData.dimensions}
                  onChange={handleInputChange}
                  required
                  placeholder="10x10x10"
                />
              </div>
              <div className="form-group">
                <label>Estimated Delivery *</label>
                <input
                  type="date"
                  name="estimatedDelivery"
                  value={formData.estimatedDelivery}
                  onChange={handleInputChange}
                  required
                />
              </div>
            </div>
          </div>

          <div className="form-section">
            <h3>Customer Information</h3>
            <div className="form-row">
              <div className="form-group">
                <label>Customer Name *</label>
                <input
                  type="text"
                  name="customerName"
                  value={formData.customerName}
                  onChange={handleInputChange}
                  required
                  placeholder="John Doe"
                />
              </div>
              <div className="form-group">
                <label>Customer Email *</label>
                <input
                  type="email"
                  name="customerEmail"
                  value={formData.customerEmail}
                  onChange={handleInputChange}
                  required
                  placeholder="john@example.com"
                />
              </div>
            </div>
          </div>

          <div className="modal-footer">
            <button type="button" className="cancel-button" onClick={onClose}>
              Cancel
            </button>
            <button type="submit" className="save-button" disabled={loading}>
              {loading ? 'Adding...' : 'Add Shipment'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddShipmentModal;
